<script>
import upgrade from '@/home/upgrade/index.vue'
export default {
  name: 'setting_index',
  components: { upgrade },
  data () {
    return {
      newPassword: '',
      active: 0,
      actionElem: '',
      scrollElem: '',
      agentConnecting: false,
      settingData: {
        BasicInfodData: {
          IsOpenNoCompleteTask: false,
          ServiceProviderInfo: '',
          VersionInfo: '',
          MechanicalCode: '',
          IsCloseForm: false,
          IsShowUpdateNotice: false
        },
        ReptilesSetting: {
          IsOpenGoogleCse: false,
          TheFirstThreadLimit: 0,
          TheSecondThreadLimit: 0,
          SELimit: 0,
          CrawLimit: 0,
          IsFilterSecondaryDomain: false,
          KeywordFilter: {
            IsFilterKeyword: false,
            KeywordList: []
          },
          AddressFilter: {
            IsFilterAddress: false,
            KeywordList: []
          },
          DeleteSetting: {
            IsOpenDelete: false,
            IsOpenEmailDelete: false,
            IsOpenLinkedInDelete: false,
            IsOpenFacebookDelete: false,
            IsOpenTwitterDelete: false,
            IsOpenInstagramDelete: false
          }
        },
        Agent: {
          IsOpenAgent: false,
          IsOpenLinkedAgent: false,
          IsOpenTwitterAgent: false,
          IsOpenFacebookAgent: false,
          IsOpenInstagramAgent: false,
          IsOpenqqEmailAgent: false,
          IsOpen163EmailAgent: false,
          IsOpen126EmailAgent: false,
          IsOpentyeahEmailAgent: false,
          AgentDataList: {
            AgentType: 0,
            AgentServer: '',
            AgentPort: '',
            Account: '',
            Password: ''
          }
        }
      },
      reptilesFilter: {
        KeywordFilter: '',
        AddressFilter: ''
      },
      upgrade: {
        show: false,
        versionData: {
          vesion: '1.0.0.9',
          versionRemark: '',
          IsForceUpdate: false,
          IsUpdate: false
        }
      }
    }
  },
  methods: {

    /**
     * @author: vince.Liang
     * @function: 加载设置数据
     * @param {none}
     * @return: undefined
     */
    loadSettingData () {
      this.SharpObj.getLocalConfigData(res => {
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        Object.assign(this.settingData, res.Data)
        if (Array.isArray(this.settingData.ReptilesSetting.KeywordFilter.KeywordList)) {
          for (let item of this.settingData.ReptilesSetting.KeywordFilter.KeywordList) {
            this.reptilesFilter.KeywordFilter = this.reptilesFilter.KeywordFilter + item + '\n'
          }
          this.reptilesFilter.KeywordFilter = this.reptilesFilter.KeywordFilter.substring(0, this.reptilesFilter.KeywordFilter.length - 1)
        }
        if (Array.isArray(this.settingData.ReptilesSetting.AddressFilter.KeywordList)) {
          for (let item of this.settingData.ReptilesSetting.AddressFilter.KeywordList) {
            this.reptilesFilter.AddressFilter = this.reptilesFilter.AddressFilter + item + '\n'
          }
          this.reptilesFilter.AddressFilter = this.reptilesFilter.AddressFilter.substring(0, this.reptilesFilter.AddressFilter.length - 1)
        }
      })
    },

    handleOnScroll (event) {
      const navContents = document.querySelectorAll('.setting-module')
      const offsetTopArr = []
      navContents.forEach(item => {
        offsetTopArr.push(item.offsetTop)
      })
      const scrollTop = event.target.scrollTop
      for (let i = 0; i < offsetTopArr.length; i++) {
        if (scrollTop <= offsetTopArr[i]) {
          this.active = i
          break
        }
      }
    },
    handleScrollTo (index) {
      this.actionElem = document.querySelectorAll('.setting-module')[index]
      this.scrollElem = document.querySelector('.setting-contain-box')
      this.scrollElem.scrollTo({
        top: this.actionElem.offsetTop,
        behavior: 'smooth'
      })
    },

    /**
     * @author: vince.Liang
     * @function: 用户检查版本更新
     * @data: 2019-3-27
     * @param {none}
     * @return: undefined
     */
    checkVersionUpdate () {
      this.SharpObj.getUpdateInfo(res => {
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        Object.assign(this.upgrade.versionData, res.Data)
        this.upgrade.show = true
      })
    },

    /**
     * @author: vince.Liang
     * @function: 添加过滤关键字
     * @param {String} type 过滤关键字类型 KeywordFilter:标题关键字，AddressFilter:网址关键字
     * @return: undefined
     */
    addFilterKeyword (type) {
      if (this.reptilesFilter[type] === '' || this.reptilesFilter[type] === '\n') {
        this.settingData.ReptilesSetting[type].KeywordList = []
      }
      let keyWordCustom = this.reptilesFilter[type].split(/\n/)
      keyWordCustom = keyWordCustom.filter((item, index) => {
        if (item === '' || keyWordCustom.indexOf(item) !== index) {
          return false
        } else {
          return true
        }
      })
      this.settingData.ReptilesSetting[type].KeywordList = keyWordCustom
    },

    /**
     * @author: vince.Liang
     * @function: 保存设置
     * @param {none}
     * @return: undefined
     */
    doSave () {
      this.SharpObj.setLocalConfigData(JSON.stringify(this.settingData), res => {
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        this.$WmlMsg(this.$lang('common.saveSuccess', '保存成功'))
      })
    },

    /**
     * @author: vince.Liang
     * @function: 应用代理
     * @param {none}
     * @return: undefined
     */
    doConnectAgent () {
      if (isNaN(Number(this.settingData.Agent.AgentDataList.AgentPort))) {
        this.$WmlMsg(this.$lang('setting.portMustNumber', '端口号必须为数字'))
        return
      }
      this.settingData.Agent.AgentDataList.AgentPort = Number(this.settingData.Agent.AgentDataList.AgentPort)
      this.agentConnecting = !this.agentConnecting
      this.SharpObj.setAgent(JSON.stringify(this.settingData), res => {
        res = JSON.parse(res)
        this.agentConnecting = !this.agentConnecting
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        this.$WmlMsg(this.$lang('setting.connectSuccess', '连接成功'))
      })
    },

    /**
     * @author: vince.Liang
     * @function: 修改密码
     * @param {none}
     * @return:undefined
     */
    async doEditPwd () {
      if (this.newPassword === '') {
        this.$WmlMsg(this.$lang('setting.pwdNoNull', '新密码不能为空'), 'warning')
        return
      }
      if (!await this.$WmlConfirm(this.$lang('setting.confirmPwdModify', '确认修改？'))) { return }
      this.SharpObj.updatePassword(this.newPassword, res => {
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
          return
        }
        this.$WmlMsg(this.$lang('setting.modifySuccess', '修改成功'))
      })
    }
  },
  created () {
    this.loadSettingData()
  },
  watch: {
    // 提示未开放自定义代理
    'settingData.Agent.IsOpenAgent' (bool) {
      if (bool) {
        this.$WmlMsg(this.$lang('setting.agentCloseNow', '自定义代理暂未开放'), 'warning')
        this.settingData.Agent.IsOpenAgent = false
      }
    }
  }
}
</script>
