<template>
  <div class="upgrade-main">
    <wml-dialog
      width="650px"
      :visible.sync="visibleTipUpgrade"
      :closeOnPressEscape="false"
      :showClose="false"
      :closeOnClickModal="false"
    >
      <div class="upgrade-tip-box">
        <div class="dialog-tit-icon">
          <i
            class="el-icon-close"
            v-if="!newVersionData.IsForceUpdate && !upgradeing"
            @click="closeUpgradeTip"
          ></i>
        </div>
        <div class="upgrade-contenttip-box">
          <h3 class="upgrade-title">{{newVersionData.Title}}</h3>
          <div class="version">{{newVersionData.Version}}</div>
          <div class="upgrade-trait-box">
            <div v-for="(item, index) of newVersionData.Description" :key="index">{{item}}</div>
          </div>
          <div class="upgrade-action-box" v-if="newVersionData.IsUpdate">
            <el-button
              type="primary"
              @click="doUpgrade"
              style="width:100%;-webkit-app-region: no-drag;"
              v-show="!upgradeing"
            >{{ $lang('upgrade.onClickUpgrade', '一键升级') }}</el-button>
            <el-progress
              :text-inside="true"
              :stroke-width="30"
              :percentage="percentage"
              :format="format"
              v-show="upgradeing"
              v-if="type === 0"
            ></el-progress>
            <el-progress
              :text-inside="true"
              :stroke-width="30"
              :percentage="percentage"
              :format="format"
              v-show="upgradeing"
              v-if="type === 1"
            ></el-progress>
          </div>
        </div>
      </div>
    </wml-dialog>
  </div>
</template>
<script>
export default {
  name: 'upgrade',
  data () {
    return {
      visibleTipUpgrade: false,
      percentage: 0,
      type: 0,
      upgradeing: false
    }
  },
  props: {
    visible: {
      type: Boolean,
      default: false
    },
    newVersionData: {
      type: Object,
      default: () => {
        return {
          IsForceUpdate: false,
          IsUpdate: false
        }
      }
    }
  },
  methods: {
    doUpgrade () {
      this.upgradeing = true
      this.SharpObj.startDownLoadAndDecompression(res => {
        res = JSON.parse(res)
        if (res.Code !== 0) {
          this.$WmlMsg(res.Msg, 'warning')
        }
      })
    },
    format (percentage) {
      if (this.type === 0) {
        return `${this.$lang('upgrade.downloadProgress', '下载进度')}${percentage}%`
      } else if (this.type === 1) {
        return `${this.$lang('upgrade.rateProgress', '解压进度')}${percentage}%`
      }
    },
    /**
     * @author: vince.Liang
     * @function: 关闭更新弹窗
     * @data: 2019-3-27
     * @param {type}
     * @return:
     */
    closeUpgradeTip () {
      this.visibleTipUpgrade = false
    },

    /**
     * @author: vince.Liang
     * @function: 绑定的window上的改变进度条的具体操作
     * @data: 2019-3-27
     * @param {Number} num 当前进度
     * @param {Number} type 当前进度条显示类型, 0:下载， 1：解压
     * @return:
     */
    changePercentage (num, type) {
      this.type = type
      this.percentage = num
      if (this.type === 1 && this.percentage >= 100) {
        window.setTimeout(_ => this.$WmlMsg(this.$lang('upgrade.upgradeSuccessTip', '更新成功,程序即将重启')), 800)
      }
    },
    /**
     * @author: vince.Liang
     * @function: 成功提示弹窗
     * @data: 2019-3-27
     * @param {String} msg 提示信息
     * @param {Number} type 提示类型 0:成功
     * @return: undefined
     */
    doSuccessUpgrade (msg, type = 0) {
      this.$WmlMsg(msg)
      if (type === 0) {
        this.$WmlMsg(msg)
      } else {
        this.$WmlMsg(msg, 'warning')
      }
    }
  },
  watch: {
    visible (val) {
      if (this.visibleTipUpgrade === val) return
      this.visibleTipUpgrade = val
    },
    visibleTipUpgrade (val) {
      this.$emit('update:visible', val)
    }
  },
  mounted () {
    window['changePercentage'] = (num, type) => this.changePercentage(num, type)
    window.doSuccessUpgrade = this.doSuccessUpgrade
  }
}
</script>

<style scoped>
.upgrade-main >>> .el-dialog__header {
  padding: 0;
}

.upgrade-tip-box {
  padding: 10px 10px 30px 10px;
  background-image: url("../../assets/image/upgradeBg.png");
  background-repeat: no-repeat;
}

.upgrade-main >>> .el-dialog__body {
  padding: 0;
}

.dialog-tit-icon {
  height: 30px;
  line-height: 30px;
  padding: 0 3px;
  text-align: right;
}

.dialog-tit-icon > i {
  font-size: 18px;
  cursor: pointer;
}

.upgrade-title {
  font-size: 23px;
  font-weight: normal;
  color: #050505;
  padding-top: 10px;
}

.version {
  font-size: 14px;
  color: #818181;
  height: 38px;
  line-height: 38px;
}

.upgrade-main >>> .upgrade-trait-option {
  color: #666;
  height: 30px;
  line-height: 30px;
}

.upgrade-action-box {
  margin-top: 30px;
}

.upgrade-contenttip-box {
  padding: 100px 23px 0;
}

.upgrade-trait-box {
  width: 100%;
}

.upgrade-main >>> .el-dialog__header {
  display: none;
}

.upgrade-main >>> .el-icon-close {
  -webkit-app-region: no-drag;
}
</style>
